using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using Timarker.Models;using Timarker_WinUI.Services;namespace Timarker_WinUI.Pages;public sealed partial class RecordsPage:Page{public RecordsPage(){InitializeComponent();Refresh();}private void Refresh()=>RecordList.ItemsSource=AppData.Current.Records.OrderByDescending(x=>x.OccurredAt).ToList();private async void Add_Click(object s,RoutedEventArgs e){var title=new TextBox{Header="发生了什么",PlaceholderText="例如：完成了周报初稿"};var detail=new TextBox{Header="补充",AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=100};var date=new CalendarDatePicker{Header="记录日期",Date=DateTimeOffset.Now};var panel=new StackPanel{Spacing=12};panel.Children.Add(title);panel.Children.Add(detail);panel.Children.Add(date);var d=new ContentDialog{XamlRoot=XamlRoot,Title="补一条记录",Content=panel,PrimaryButtonText="保存记录",CloseButtonText="取消"};if(await d.ShowAsync()!=ContentDialogResult.Primary||string.IsNullOrWhiteSpace(title.Text))return;AppData.Current.Records.Add(new ActivityRecord{Title=title.Text.Trim(),Detail=detail.Text.Trim(),OccurredAt=(date.Date??DateTimeOffset.Now).DateTime});AppData.Current.Save();Refresh();}}
